if (parentScene && !this.isLinked) {
    if (parentScene.composer) {
        this.nestedScene.composer = parentScene.composer;
        this.nestedScene.device = parentScene.composer.device;
        this.nestedScene.compute = parentScene.composer.compute;
        this.nestedScene.renderer = parentScene.composer.renderer;
        this.nestedScene.stateManager = parentScene.composer.stateManager;
