import { Scene, SubScene, Circle, NumberPlane, Text, Color, Vec3 } from "retiam";

// 1. Author independent child widget scene
class ClockWidgetScene extends Scene {
    async run() {
        const face = new Circle(2.0, { stroke: Color.WHITE, stroke_width: 0.1 });
        const secondHand = new Circle(0.1, { fill: Color.RED });
        this.add(face, secondHand);

        this.always(({ time }) => {
            secondHand.transform.position = new Vec3(
                Math.cos(-time * 2.0) * 1.6,
                Math.sin(-time * 2.0) * 1.6,
                0
            );
        });
    }
}

// 2. Author master presentation scene
const masterScene = new Scene({ canvas });

const header = new Text("DASHBOARD OVERVIEW", { fontSize: 48, fill: Color.CYAN });
header.transform.position = [0, 4, 0];
masterScene.add(header);

// 3. Mount child scene as an entity
const clockSubScene = new SubScene(new ClockWidgetScene());
clockSubScene.transform.scale = 0.8;
clockSubScene.transform.position = [5, 2, 0];
masterScene.add(clockSubScene);
